import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Evaluating values (Grafana, VIS, scripts)","description":"","frontmatter":{"order":4,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/04.werte-auswerten.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/werte-auswerten.md","filePath":"adapter/sourceanalytix/anleitungen/werte-auswerten.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/anleitungen/werte-auswerten.md"};function r(h,s,l,o,d,p){return e(),i("div",null,[...s[0]||(s[0]=[t('<h1 id="evaluating-values-grafana-vis-scripts" tabindex="-1">Evaluating values (Grafana, VIS, scripts) <a class="header-anchor" href="#evaluating-values-grafana-vis-scripts" aria-label="Permalink to &quot;Evaluating values (Grafana, VIS, scripts)&quot;">​</a></h1><p><a id="evaluate-across-years-adjusting-everything"></a></p><h2 id="how-do-i-evaluate-values-across-several-years-without-adjusting-everything-every-year" tabindex="-1">How do I evaluate values across several years without adjusting everything every year? <a class="header-anchor" href="#how-do-i-evaluate-values-across-several-years-without-adjusting-everything-every-year" aria-label="Permalink to &quot;How do I evaluate values across several years without adjusting everything every year?&quot;">​</a></h2><p>Use the states under <code>sourceanalytix.0.&lt;device&gt;.currentYear</code>. Their IDs never change, not even at the turn of the year. To compare across years, record the previous periods with a history adapter or read the archive under <code>sourceanalytix.0.&lt;device&gt;.&lt;year&gt;</code>.</p><table tabindex="0"><thead><tr><th>Folder</th><th>Content</th></tr></thead><tbody><tr><td><code>currentYear.&lt;category&gt;.01_currentDay</code> to <code>05_currentYear</code></td><td>running periods</td></tr><tr><td><code>currentYear.&lt;category&gt;.01_previousDay</code> to <code>05_previousYear</code></td><td>closed previous periods</td></tr><tr><td><code>currentYear.&lt;category&gt;.weeks</code>, <code>months</code>, <code>quarters</code></td><td>every week, month and quarter of this year</td></tr><tr><td><code>&lt;year&gt;.&lt;category&gt;.weeks</code>, <code>months</code>, <code>quarters</code></td><td>archive of a calendar year, a new folder each year</td></tr></tbody></table><p><code>&lt;category&gt;</code> is <code>consumed</code> or <code>delivered</code>, <code>costs</code> or <code>earnings</code>, and <code>meterReadings</code>.</p><p>You decide which folders are created in the instance settings under &quot;Main settings&quot;: &quot;Current year&quot; for <code>currentYear</code>, &quot;Year statistics&quot; for the archive. If you turn an option off, the page asks first, because SourceAnalytix then deletes those states of the current year. Earlier years stay.</p><p>For long-term charts, record for example <code>03_previousMonth</code> and <code>05_previousYear</code>. Each value arrives once per period, timestamped 23:59:59 on the last day of the period. A year&#39;s weeks are in the folder of the year the calendar week belongs to.</p><p><strong>See also:</strong> <a href="#datapoints-use-grafana-influxdb">Datapoints for Grafana/InfluxDB</a> · <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Instance settings</a> · <a href="./../referenz/states-und-meldungen#happens-turn-year">Turn of the year</a></p><p><a id="datapoints-use-grafana-influxdb"></a></p><h2 id="which-datapoints-do-i-use-for-grafana-influxdb" tabindex="-1">Which datapoints do I use for Grafana/InfluxDB? <a class="header-anchor" href="#which-datapoints-do-i-use-for-grafana-influxdb" aria-label="Permalink to &quot;Which datapoints do I use for Grafana/InfluxDB?&quot;">​</a></h2><p>For bar charts, the previous periods under <code>currentYear.&lt;category&gt;</code>: <code>01_previousDay</code>, <code>02_previousWeek</code> and <code>03_previousMonth</code>. They get exactly one value per period, even when it is 0. For your own evaluations, <code>cumulativeReading</code> is enough.</p><table tabindex="0"><thead><tr><th>Chart</th><th>State</th></tr></thead><tbody><tr><td>Daily bars</td><td><code>01_previousDay</code></td></tr><tr><td>Compare weeks</td><td><code>02_previousWeek</code></td></tr><tr><td>Compare months</td><td><code>03_previousMonth</code></td></tr><tr><td>Today&#39;s curve</td><td><code>01_currentDay</code></td></tr><tr><td>Calculate everything yourself</td><td><code>cumulativeReading</code></td></tr></tbody></table><ol><li>On the &quot;Objects&quot; tab, turn on recording with your history adapter for these states, as a number.</li><li>Plot them in Grafana as bars without further summing. Each point already is the consumption of the whole period.</li></ol><p>The first value arrives after the first period rollover, so for <code>01_previousDay</code> after midnight.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Yesterday, last week, last month</a> · <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">cumulativeReading</a></p><p><a id="visualise-values-vis-flot-habpanel"></a></p><h2 id="how-do-i-visualize-the-values-in-vis-flot-habpanel-and-the-history" tabindex="-1">How do I visualize the values in VIS, Flot, HabPanel and the history? <a class="header-anchor" href="#how-do-i-visualize-the-values-in-vis-flot-habpanel-and-the-history" aria-label="Permalink to &quot;How do I visualize the values in VIS, Flot, HabPanel and the history?&quot;">​</a></h2><p>SourceAnalytix delivers states, not charts. For curves, record states with a history adapter and show them in Flot, eCharts, Grafana or a VIS widget. For tables without a database, <code>statisticsJson</code> holds all values of the current year.</p><p>The previous periods are timestamped 23:59:59 on the last day of their period, even if a rollover was caught up later. Yesterday&#39;s value therefore lands on yesterday in the history, and you get a list of daily values with dates.</p><p>Bind single values directly, for example <code>01_currentDay</code> for &quot;Today&quot;. With the &quot;Weekday&quot; option, the days of the current week are under <code>currentYear.&lt;category&gt;.currentWeek</code>.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#json-values-vis">Is there a JSON with all values?</a> · <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">States for weeks, months and weekdays</a></p><p><a id="read-sourceanalytix-values-script"></a></p><h2 id="how-do-i-read-sourceanalytix-values-in-a-script" tabindex="-1">How do I read SourceAnalytix values in a script? <a class="header-anchor" href="#how-do-i-read-sourceanalytix-values-in-a-script" aria-label="Permalink to &quot;How do I read SourceAnalytix values in a script?&quot;">​</a></h2><p>With <code>getState</code>. Every value is a state under <code>sourceanalytix.0.&lt;device&gt;</code>, where <code>&lt;device&gt;</code> is the &quot;Technical ID&quot; in the source&#39;s detail view (under &quot;For experts&quot;). You read past years by putting the year into the ID.</p><p>This month and the same month last year:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> root</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sourceanalytix.0.power&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> months</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;01_January&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;02_February&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;03_March&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;04_April&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;05_May&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;06_June&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;07_July&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;08_August&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;09_September&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;10_October&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;11_November&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;12_December&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> now</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Date</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> month</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> months[now.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getMonth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()];</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> thisMonth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.currentYear.consumed.03_currentMonth`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).val;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> lastYearId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getFullYear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.consumed.months.${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">month</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> lastYear</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> existsState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lastYearId) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lastYearId).val </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`This month: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">thisMonth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}, last year: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lastYear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Last year&#39;s folder only exists if &quot;Year statistics&quot; › &quot;Months&quot; was on back then. For last month or last year you don&#39;t need a date: <code>03_previousMonth</code> and <code>05_previousYear</code>.</p><p>All technical IDs with their source datapoint:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;getUsedOutputIds&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result)));</span></span></code></pre></div><p>Don&#39;t write to SourceAnalytix states; the next value overwrites them. For corrections, use the <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">source&#39;s actions</a>.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">What is the output ID?</a> · <a href="./../referenz/states-und-meldungen#sendto-commands-info-states">sendTo commands</a></p>',32)])])}const u=a(n,[["render",r]]);export{c as __pageData,u as default};
